SELECT jsonb_build_object('relation',(SELECT to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'] FROM pg_class c WHERE c.oid='public.rake_records'::regclass),
'columns',(SELECT jsonb_agg(jsonb_build_object('attribute',to_jsonb(a),'type',format_type(a.atttypid,a.atttypmod),'default',(SELECT pg_get_expr(d.adbin,d.adrelid)FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum))ORDER BY a.attnum)FROM pg_attribute a WHERE a.attrelid='public.rake_records'::regclass AND a.attnum>0),
'constraints',(SELECT COALESCE(jsonb_agg(to_jsonb(k)||jsonb_build_object('definition',pg_get_constraintdef(k.oid,true))ORDER BY k.oid),'[]'::jsonb)FROM pg_constraint k WHERE k.conrelid='public.rake_records'::regclass),
'indexes',(SELECT COALESCE(jsonb_agg(to_jsonb(i)||jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'index_relation_catalog',to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid'])ORDER BY i.indexrelid),'[]'::jsonb)FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid='public.rake_records'::regclass AND c.relname NOT IN('rake_records_tournament_small_evidence_cover','rake_records_tournament_large_evidence_keys')),
 'triggers',(SELECT COALESCE(jsonb_agg(to_jsonb(t)||jsonb_build_object('definition',pg_get_triggerdef(t.oid))ORDER BY t.oid),'[]'::jsonb)FROM pg_trigger t WHERE t.tgrelid='public.rake_records'::regclass),
 'policies',(SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object('using_expression',pg_get_expr(p.polqual,p.polrelid),'check_expression',pg_get_expr(p.polwithcheck,p.polrelid))ORDER BY p.oid),'[]'::jsonb)FROM pg_policy p WHERE p.polrelid='public.rake_records'::regclass),
 'schemas',(SELECT jsonb_agg(to_jsonb(n)ORDER BY n.oid)FROM pg_namespace n WHERE n.nspname IN('public','smarter_private')),
 'owners',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'definition_md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'metadata',to_jsonb(p))ORDER BY p.oid)FROM pg_proc p WHERE p.oid IN(SELECT(r->'metadata'->>'oid')::oid FROM jsonb_array_elements(expected->'owners')r)))INTO actual;
